// Scene direction is expressed in elapsed output seconds, independently of source playback position.
let cues=[{t:0,name:'Establish the scene',v:15},{t:8,name:'Something is wrong',v:45},{t:20,name:'The threat arrives',v:100},{t:30,name:'Aftermath',v:0}],sceneRunning=false,sceneTime=0,stateHold=0,pendingState=null;
const originalHold=hold;hold=function(){originalHold();sceneRunning=false;pendingState=null};
aim=function(v,instant=false){target=v;const d=Number($(v<rate?'fall':'ramp').value);let wait=0;if(!instant&&$('align').value!=='now'){const step=$('align').value==='bar'?4:1,beat=audio.currentTime*Number($('base').value)/60;const remaining=(step-beat%step)%step;wait=remaining*60/(Number($('base').value)*rate)}ramp=instant?null:{from:rate,to:v,t:-wait,d};if(instant)rate=v;};
$('fall').oninput=()=>$('fallValue').textContent=$('fall').value;
function sortedCues(){return [...cues].sort((a,b)=>a.t-b.t)}
function drawCues(){const rows=$('cueRows');rows.replaceChildren();cues.forEach((c,i)=>{let row=document.createElement('div');row.className='cuegrid';for(const key of ['t','name','v']){let input=document.createElement('input');input.type=key==='name'?'text':'number';input.value=c[key];input.setAttribute('aria-label',`${key==='t'?'Time':key==='v'?'Intensity':'Direction'} for cue ${i+1}`);if(key!=='name'){input.min=0;input.max=key==='t'?600:100;input.step=key==='t'?.1:1}input.onchange=()=>{hold();let value=key==='name'?input.value.slice(0,80):Math.max(0,Math.min(key==='t'?600:100,Number(input.value)||0));if(key==='t'&&cues.some((x,j)=>j!==i&&Math.abs(x.t-value)<.001)){$('deliveryStatus').textContent='Cue times must be different.';input.value=c.t;return}c[key]=value;input.value=value;graph()};row.append(input)}let b=document.createElement('button');b.textContent='Remove';b.setAttribute('aria-label',`Remove cue ${i+1}`);b.disabled=cues.length<=2;b.onclick=()=>{hold();cues.splice(i,1);drawCues()};row.append(b);rows.append(row)});graph()}
function graph(){const sorted=sortedCues(),end=Math.max(1,sorted.at(-1).t),pts=sorted.map(c=>[20+c.t/end*860,125-c.v]);let d='';pts.forEach((p,i)=>{if(!i)d=`M${p[0]} ${p[1]}`;else {let prev=pts[i-1],mid=(prev[0]+p[0])/2;d+=$('shape').value==='linear'?`L${p[0]} ${p[1]}`:`C${mid} ${prev[1]} ${mid} ${p[1]} ${p[0]} ${p[1]}`}});$('cueGraph').innerHTML=`<path d="M20 25H880 M20 75H880 M20 125H880" stroke="#344037"/><path d="${d}" fill="none" stroke="#d1ef87" stroke-width="3"/>`+pts.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#d1ef87"/>`).join('');}
$('shape').onchange=graph;$('addCue').onclick=()=>{if(cues.length>=24||Math.max(...cues.map(c=>c.t))>=595){$('deliveryStatus').textContent='Maximum 24 cues.';return}hold();cues.push({t:Math.max(...cues.map(c=>c.t))+5,name:'New direction',v:50});drawCues()};
function sceneValue(t){let s=sortedCues();if(t<=s[0].t)return s[0].v;for(let i=1;i<s.length;i++)if(t<=s[i].t){let x=ease((t-s[i-1].t)/(s[i].t-s[i-1].t));return s[i-1].v+(s[i].v-s[i-1].v)*x}return s.at(-1).v}
$('runCues').onclick=async()=>{hold();audio.pause();audio.currentTime=0;sceneTime=0;rate=target=map(sceneValue(0)/100);audio.playbackRate=rate;sceneRunning=true;await play();$('status').textContent='Following scene cues · arrival targets override transition times.'};$('holdCues').onclick=()=>{hold();$('status').textContent='Holding the current scene tempo.'};
function sceneTab(game){$('gamePanel').classList.toggle('hidden',!game);$('filmPanel').classList.toggle('hidden',game);$('filmTab').classList.toggle('primary',!game);$('gameTab').classList.toggle('primary',game)}$('filmTab').onclick=()=>sceneTab(false);$('gameTab').onclick=()=>sceneTab(true);
function triggerState(v,name){hold();$('intensity').value=v;aim(map(v/100));stateHold=number('minHold',0,20,1);$('gameStatus').textContent=name+' · directing intensity to '+v+'%';}
document.querySelectorAll('[data-state]').forEach(b=>b.onclick=()=>{let v=Number(b.dataset.state),name=b.textContent;if(stateHold>0&&!audio.paused){pendingState={v,name};$('gameStatus').textContent=name+' queued · waiting for minimum hold.'}else triggerState(v,name)});
window.sceneStep=dt=>{stateHold=Math.max(0,stateHold-dt);if(stateHold===0&&pendingState){let p=pendingState;pendingState=null;triggerState(p.v,p.name)}if(sceneRunning){sceneTime+=dt;rate=target=map(sceneValue(sceneTime)/100);$('intensity').value=sceneValue(sceneTime);if(sceneTime>=sortedCues().at(-1).t){sceneRunning=false;$('status').textContent='Cue timeline complete · holding final target.'}}$('sceneClock').textContent=String(Math.floor(sceneTime/60)).padStart(2,'0')+':'+(sceneTime%60).toFixed(3).padStart(6,'0');};
audio.addEventListener('loadedmetadata',()=>{$('runCues').disabled=$('record').disabled=false});audio.addEventListener('emptied',()=>{$('runCues').disabled=$('record').disabled=true});audio.addEventListener('pause',()=>{if(captureNode)captureNode.port.postMessage({active:false})});audio.addEventListener('play',()=>{if(captureNode&&recording)captureNode.port.postMessage({active:true})});
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000)}
function direction(){return {format:'pulse-direction',version:1,name:$('name').value||'Scene direction',source:$('filename').textContent,settings:Object.fromEntries(['base','low','high','ramp','fall','intensity','duration','minHold'].map(id=>[id,Number($(id).value)])),shape:$('shape').value,align:$('align').value,seq:$('seq').value,pitch:$('pitch').checked,loop:$('loop').checked,cues};}
$('exportPreset').onclick=()=>{download(new Blob([JSON.stringify(direction(),null,2)],{type:'application/json'}),'pulse-direction.json');$('deliveryStatus').textContent='Direction exported. Send it with the matching audio file.'};
$('importPreset').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100000)throw Error();const d=JSON.parse(await file.text());const limits={base:[30,300],low:[50,200],high:[50,200],ramp:[.2,20],fall:[.2,30],intensity:[0,100],duration:[2,300],minHold:[0,20]};if(d.format!=='pulse-direction'||d.version!==1||!d.settings||!Array.isArray(d.cues)||d.cues.length<2||d.cues.length>24)throw Error();for(const [k,[lo,hi]]of Object.entries(limits))if(typeof d.settings[k]!=='number'||!Number.isFinite(d.settings[k])||d.settings[k]<lo||d.settings[k]>hi)throw Error();if(d.settings.high<d.settings.low||!['smooth','linear'].includes(d.shape)||!['now','beat','bar'].includes(d.align)||!['build','surge','settle'].includes(d.seq)||typeof d.pitch!=='boolean'||typeof d.loop!=='boolean')throw Error();if(d.cues.some(c=>typeof c.name!=='string'||c.name.length>80||!Number.isFinite(c.t)||c.t<0||c.t>600||!Number.isFinite(c.v)||c.v<0||c.v>100)||new Set(d.cues.map(c=>c.t)).size!==d.cues.length)throw Error();hold();for(let k of Object.keys(limits))$(k).value=d.settings[k];for(let k of ['shape','align','seq'])$(k).value=d[k];$('pitch').checked=d.pitch;audio.preservesPitch=d.pitch;$('loop').checked=audio.loop=d.loop;$('name').value=String(d.name||'Imported direction').slice(0,45);$('fallValue').textContent=d.settings.fall;cues=d.cues.map(c=>({t:c.t,name:c.name,v:c.v}));drawCues();draw();liveTarget();$('deliveryStatus').textContent='Direction imported. Load its matching audio separately.'}catch{$('deliveryStatus').textContent='Import rejected: choose a valid Pulse direction JSON. Existing direction was preserved.'}e.target.value=''};
let ctx,captureNode,recording=false,chunks=[],sampleCount=0;
async function captureSetup(){if(ctx&&captureNode){await ctx.resume();return}ctx=new AudioContext();await ctx.audioWorklet.addModule('capture.js');captureNode=new AudioWorkletNode(ctx,'pulse-capture',{outputChannelCount:[2]});const source=ctx.createMediaElementSource(audio);source.connect(captureNode).connect(ctx.destination);captureNode.port.onmessage=e=>{if(e.data.done){finishDownload();return}if(!recording)return;chunks.push(e.data);sampleCount+=e.data[0].length;$('recordTime').textContent=(sampleCount/ctx.sampleRate).toFixed(1)+'s / 120s';if(sampleCount>=ctx.sampleRate*120)finishCapture()};await ctx.resume()}
$('record').onclick=async()=>{try{await captureSetup();chunks=[];sampleCount=0;recording=true;$('record').disabled=true;$('finish').disabled=false;captureNode.port.postMessage({active:!audio.paused});$('deliveryStatus').textContent='Recording armed. Press Play or start a timeline. Pauses are excluded.'}catch{recording=false;$('record').disabled=false;$('finish').disabled=true;if(ctx&&!captureNode){ctx.close();ctx=null}$('deliveryStatus').textContent='WAV capture is unavailable in this browser. Try current desktop Chrome or Safari.'}};
function finishCapture(){if(!recording)return;$('finish').disabled=true;captureNode.port.postMessage({finish:true})}function finishDownload(){recording=false;$('record').disabled=false;if(!sampleCount){$('deliveryStatus').textContent='No playback captured. Start playback while recording.';return}const n=sampleCount,b=new ArrayBuffer(44+n*4),v=new DataView(b),str=(o,s)=>{for(let i=0;i<s.length;i++)v.setUint8(o+i,s.charCodeAt(i))};str(0,'RIFF');v.setUint32(4,36+n*4,true);str(8,'WAVEfmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,2,true);v.setUint32(24,ctx.sampleRate,true);v.setUint32(28,ctx.sampleRate*4,true);v.setUint16(32,4,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,n*4,true);let offset=44;for(const pair of chunks)for(let i=0;i<pair[0].length;i++)for(let c=0;c<2;c++){let x=Math.max(-1,Math.min(1,pair[c][i]));v.setInt16(offset,x<0?x*32768:x*32767,true);offset+=2}download(new Blob([b],{type:'audio/wav'}),'pulse-take.wav');chunks=[];$('deliveryStatus').textContent=`WAV downloaded · ${(n/ctx.sampleRate).toFixed(2)} seconds · ${ctx.sampleRate} Hz stereo.`;}$('finish').onclick=finishCapture;audio.addEventListener('ended',()=>{if(recording)finishCapture()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&!audio.paused){audio.pause();$('status').textContent='Paused while tab is hidden to protect timing. Resume when ready.'}});drawCues();
// Starting a new direction always takes ownership from the previous mode.
const runSequence=$('run').onclick;$('run').onclick=async()=>{hold();await runSequence()};
$('calm').onclick=()=>{hold();$('intensity').value=0;liveTarget()};
const resetPlayback=$('stop').onclick;$('stop').onclick=()=>{resetPlayback();sceneTime=0;stateHold=0;$('sceneClock').textContent='00:00.000'};
